        if len(self.cache) >= self.capacity:
            evicted_key, _ = self.cache.popitem(last=False)

        self.cache[key] = value
        return evicted_key

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        # Check membership without changing recency
        return key in self.cache

    def keys(self):
        # Return keys from least to most recently used
        # OrderedDict maintains insertion order, and we move_to_end on usage,
        # so the current order in the dict is least-to-most recently used
        return list(self.cache.keys())

    def resize(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        evicted = []
        # Evict least recently used keys until we fit the new capacity
        while len(self.cache) > self.capacity:
            evicted_key, _ = self.cache.popitem(last=False)
            evicted.append(evicted_key)

        return evicted
