from collections import OrderedDict
import time


class LRUCache:
    def __init__(self, capacity: int, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl is not None:
            if not isinstance(ttl, (int, float)) or ttl <= 0:
                raise ValueError("TTL must be a number greater than 0")

        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache = OrderedDict()  # key -> {'value': v, 'time_stored': t, 'expired_counted': bool}

        # Statistics
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _is_expired(self, entry):
        """Check if an entry is expired."""
        if self._ttl is None:
            return False
        return self._clock() - entry['time_stored'] >= self._ttl

    def _mark_expired(self, key):
        """Mark an entry as expired counted if it hasn't been counted yet."""
        if key in self._cache:
            entry = self._cache[key]
            if self._is_expired(entry) and not entry['expired_counted']:
                entry['expired_counted'] = True
                self._expirations += 1
                return True
        return False

    def get(self, key, default=None):
        """Get value by key. Returns default if not found or expired."""
        if key not in self._cache:
            self._misses += 1
            return default

        entry = self._cache[key]
        if self._is_expired(entry):
            if not entry['expired_counted']:
                entry['expired_counted'] = True
                self._expirations += 1
            self._misses += 1
            return default

        # Valid entry: mark as recently used and count as hit
        self._cache.move_to_end(key)
        self._hits += 1
        return entry['value']

    def put(self, key, value):
        """Put key-value pair. Returns evicted key if eviction occurred."""
        now = self._clock()

        # If key exists, check if it's expired
        if key in self._cache:
            entry = self._cache[key]
            if self._is_expired(entry):
                # Expired entry: remove it and count expiration if not counted
                if not entry['expired_counted']:
                    entry['expired_counted'] = True
                    self._expirations += 1
                # Remove expired entry
                del self._cache[key]
            else:
                # Update existing valid entry
                self._cache.move_to_end(key)
                self._cache[key] = {
                    'value': value,
                    'time_stored': now,
                    'expired_counted': False
                }
                return None

        # Key is new or was expired and removed
        # Clean up expired entries to count them properly for capacity check
        self._cleanup_expired_for_capacity()

        # Check if we need to evict based on unexpired count
        unexpired_count = self._count_unexpired()

        evicted_key = None
        if unexpired_count >= self._capacity:
            # Find LRU unexpired key to evict
            lru_key = self._find_lru_unexpired()
            if lru_key is not None:
                del self._cache[lru_key]
                self._evictions += 1
                evicted_key = lru_key

        # Add new entry
        self._cache[key] = {
            'value': value,
            'time_stored': now,
            'expired_counted': False
        }

        return evicted_key

    def _cleanup_expired_for_capacity(self):
        """Count expired entries that haven't been counted yet (for stats)."""
        if self._ttl is None:
            return
        for key in list(self._cache.keys()):
            entry = self._cache[key]
            if self._is_expired(entry) and not entry['expired_counted']:
                entry['expired_counted'] = True
                self._expirations += 1

    def _count_unexpired(self):
        """Count the number of unexpired entries."""
        count = 0
        for entry in self._cache.values():
            if not self._is_expired(entry):
                count += 1
        return count

    def _find_lru_unexpired(self):
        """Find the least recently used unexpired key."""
        for key, entry in self._cache.items():
            if not self._is_expired(entry):
                return key
        return None

    def __len__(self):
        """Return count of unexpired entries."""
        count = 0
        for entry in self._cache.values():
            if not self._is_expired(entry):
                count += 1
        return count

    def __contains__(self, key):
        """Check if key exists and is unexpired."""
        if key not in self._cache:
            return False
        return not self._is_expired(self._cache[key])

    def keys(self):
        """Return list of unexpired keys."""
        return [k for k, entry in self._cache.items() if not self._is_expired(entry)]

    def resize(self, capacity: int):
        """Resize the cache. Returns list of evicted keys."""
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")

        self._capacity = capacity

        # Count expired entries for stats
        self._cleanup_expired_for_capacity()

        evicted_keys = []

        while self._count_unexpired() > self._capacity:
            lru_key = self._find_lru_unexpired()
            if lru_key is None:
                break
            del self._cache[lru_key]
            self._evictions += 1
            evicted_keys.append(lru_key)

        return evicted_keys

    def stats(self):
        """Return cache statistics."""
        return {
            'hits': self._hits,
            'misses': self._misses,
            'evictions': self._evictions,
            'expirations': self._expirations
        }
