        """Increment expiration stat and mark record as counted."""
        if not record[2]:
            self.stats_dict["expirations"] += 1
            record[2] = True
        # Remove from cache immediately so it doesn't count for future operations
        if key in self.cache:
            del self.cache[key]

    def _cleanup_expired(self):
        """Iterate through cache, remove and count expired entries."""
        keys_to_remove = []
        for key, record in self.cache.items():
            if self._is_expired(record):
                if not record[2]:
                    self.stats_dict["expirations"] += 1
                    record[2] = True
                keys_to_remove.append(key)

        for key in keys_to_remove:
            del self.cache[key]

    def _count_unexpired(self):
        """Return number of unexpired entries, cleaning up expired ones as it goes."""
        count = 0
        for key, record in list(self.cache.items()):
            if self._is_expired(record):
                if not record[2]:
                    self.stats_dict["expirations"] += 1
                    record[2] = True
                del self.cache[key]
            else:
                count += 1
        return count

    def _find_lru_unexpired(self):
        """Find and remove the least recently used unexpired key. Returns the key."""
        for key, record in list(self.cache.items()):
            if not self._is_expired(record):
                del self.cache[key]
                self.stats_dict["evictions"] += 1
                return key
            else:
                # If we encounter an expired one during LRU search, clean it up
                if not record[2]:
                    self.stats_dict["expirations"] += 1
                    record[2] = True
                del self.cache[key]
