            # We need to ensure expired entries are not counted.
            # The simplest way is to iterate and clean/count.
            unexpired_count = self._count_unexpired()

            if unexpired_count >= self.capacity:
                evicted_key = self._find_lru_unexpired()

            self.cache[key] = [value, self.clock(), False]
            self.cache.move_to_end(key)

        return evicted_key

    def __len__(self):
        return self._count_unexpired()

    def __contains__(self, key):
        if key not in self.cache:
            return False
        record = self.cache[key]
        if self._is_expired(record):
            self._mark_expired(key, record)
            return False
        return True

    def keys(self):
        # Cleanup expired and return remaining keys
        self._cleanup_expired()
        return list(self.cache.keys())

    def resize(self, capacity):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity

        # Clean up expired first
        self._cleanup_expired()

        evicted = []
        current_unexpired = len(self.cache) # After cleanup, all are unexpired

        while current_unexpired > self.capacity:
            evicted_key = self._find_lru_unexpired()
            if evicted_key is None:
                break
            evicted.append(evicted_key)
            current_unexpired -= 1

        return evicted

    def stats(self):
        return dict(self.stats_dict)
