import re

class ParseError(ValueError):
    def __init__(self, message: str, lineno: int):
        self.lineno = lineno
        # Ensure message contains "line N" where N is lineno
        full_message = f"{message} at line {lineno}"
        super().__init__(full_message)


class Config:
    def __init__(self, data: dict[str, dict[str, str]]):
        # dict preserves insertion order in Python 3.7+
        self._data = data

    def sections(self) -> list[str]:
        return list(self._data.keys())

    def keys(self, section: str) -> list[str]:
        if section not in self._data:
            raise KeyError(section)
        return list(self._data[section].keys())

    def get(self, section: str, key: str, default=None) -> str | None:
        if section in self._data and key in self._data[section]:
            return self._data[section][key]
        return default

    def getint(self, section: str, key: str, default=None) -> int | None:
        val = self.get(section, key)
        if val is None:
            return default

        # Strict validation: optional sign followed by digits only
        if not re.match(r'^[+-]?\d+$', val):
            raise ValueError(f"invalid literal for int() with base 10: '{val}'")

        return int(val)

    def getbool(self, section: str, key: str, default=None) -> bool | None:
        val = self.get(section, key)
        if val is None:
            return default

        v = val.strip().lower()
        if v in ('true', 'yes', 'on', '1'):
            return True
        if v in ('false', 'no', 'off', '0'):
            return False

        raise ValueError(f"invalid boolean value: '{val}'")

    def getlist(self, section: str, key: str, default=None) -> list[str] | None:
        val = self.get(section, key)
        if val is None:
            return default

        # Split on commas, strip each item, drop empty items
        parts = val.split(',')
        result = []
        for p in parts:
            stripped = p.strip()
            if stripped:
                result.append(stripped)
        return result


def parse(text: str) -> Config:
    data: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    current_key: str | None = None

    lines = text.splitlines()

    for i, line in enumerate(lines):
        lineno = i + 1

        # Check for blank line or comment
        stripped_line = line.strip()
        if not stripped_line:
            # Blank line resets continuation context
            current_key = None
            continue

        if stripped_line[0] in (';', '#'):
            # Comment resets continuation context
            current_key = None
            continue

        # Check for continuation line
        if line[0] in (' ', '\t'):
            # Indented line
            if current_key is None:
                raise ParseError("indented line that is not a valid continuation line", lineno)

            # Append to current key's value
            # Note: current_section must be not None if current_key is not None
            val = data[current_section][current_key]
            if val:
                data[current_section][current_key] += "\n" + stripped_line
            else:
                data[current_section][current_key] = stripped_line
            continue

        # If we reach here, the line is not blank, not a comment, and not indented.
        # It must be a section header or a key line.

        # Reset continuation context because a new non-continued line appeared
        current_key = None

        if stripped_line.startswith('['):
            # Section header
            match = re.match(r'^\[\s*([^\]]+)\s*\]$', stripped_line)
            if not match:
                # It starts with [ but doesn't match the full pattern
                # E.g. [name or [name] extra
                raise ParseError("invalid section header", lineno)

            section_name = match.group(1).strip()
            if not section_name:
                raise ParseError("empty section name", lineno)

            if section_name in data:
                raise ParseError(f"duplicate section '{section_name}'", lineno)

            data[section_name] = {}
            current_section = section_name
            continue

        if '=' in stripped_line:
            # Key line
            if current_section is None:
                raise ParseError("key line before any section header", lineno)

            # Split at first '='
            key_part, value_part = stripped_line.split('=', 1)
            key = key_part.strip()
            value = value_part.strip()

            if not key:
                raise ParseError("empty key", lineno)

            if key in data[current_section]:
                raise ParseError(f"duplicate key '{key}' in section '{current_section}'", lineno)

            data[current_section][key] = value
            current_key = key
            continue

        # If it's not a section, not a key line, and not a comment/blank/continuation
        raise ParseError("invalid line format", lineno)

    return Config(data)
