        is_num_a = ident_a.isdigit()
        is_num_b = ident_b.isdigit()

        if is_num_a and is_num_b:
            # Numeric identifiers are compared as integers
            diff = int(ident_a) - int(ident_b)
            if diff != 0:
                return -1 if diff < 0 else 1
        elif is_num_a:
            # Numeric identifiers have lower precedence than non-numeric
            return -1
        elif is_num_b:
            return 1
        else:
            # Both alphanumeric, compare as strings
            if ident_a < ident_b:
                return -1
            elif ident_a > ident_b:
                return 1

    # If all compared parts equal, the longer list has higher precedence
    if len(a) < len(b):
