        return Version(major, minor, patch, prerelease, build)

    @staticmethod
    def _parse_partial(text: str) -> "Version":
        """
        Parse a partial version string for range specs.
        Fills missing minor/patch with 0.
        """
        if not isinstance(text, str):
            raise ValueError("Partial version text must be a string")

        match = _PARTIAL_VERSION_RE.match(text)
        if not match:
            raise ValueError(f"Invalid partial version string: {text!r}")

