    # Use partial parsing for range versions
    try:
        target = Version._parse_partial(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in comparator: {ver_str!r}")

    # Perform comparison
    if op == "=":
        # Equality with partials usually implies exact match to the expanded version?
        # The spec says "bare V means =V". And partials expand.
        # "1" means "1.0.0". So =1 matches 1.0.0.
        return v == target
