        match = _SEMVER_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid semantic version: '{text}'")

        major_str = match.group('major')
        minor_str = match.group('minor')
        patch_str = match.group('patch')
        pre_str = match.group('prerelease')
        build_str = match.group('build')

        # The regex guarantees structure, but let's ensure no weird whitespace or prefixes slipped through
        # The regex is anchored, so it's strict.

        major = int(major_str)
        minor = int(minor_str)
        patch = int(patch_str)

        prerelease = tuple(pre_str.split('.')) if pre_str else ()
        build = tuple(build_str.split('.')) if build_str else ()

        _validate_identifiers(prerelease, is_prerelease=True)
        # Build identifiers don't need leading zero check per prompt

        return cls(major, minor, patch, prerelease, build)

    def __str__(self):
        result = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            result += "-" + ".".join(self.prerelease)
        if self.build:
            result += "+" + ".".join(self.build)
        return result

    def __repr__(self):
        return f"Version('{str(self)}')"

    def _compare_prerelease(self, other_pre):
        """
        Compares two prerelease tuples.
        Returns -1, 0, or 1.
        """
        pre1 = self.prerelease
        pre2 = other_pre

        # No pre-release has higher precedence than having pre-release
        if not pre1 and not pre2:
            return 0
        if not pre1:
            return 1 # self is release, other is prerelease -> self > other
        if not pre2:
            return -1 # self is prerelease, other is release -> self < other

        # Compare identifiers left to right
        for i in range(max(len(pre1), len(pre2))):
            if i >= len(pre1):
                return -1 # self is shorter -> lower
            if i >= len(pre2):
                return 1 # other is shorter -> lower

            ident1 = pre1[i]
            ident2 = pre2[i]

            is_num1 = _NUMERIC_ONLY_RE.match(ident1) is not None
            is_num2 = _NUMERIC_ONLY_RE.match(ident2) is not None

            if is_num1 and is_num2:
                v1 = int(ident1)
                v2 = int(ident2)
                if v1 != v2:
                    return -1 if v1 < v2 else 1
            elif is_num1:
                # Numeric identifier is always lower than alphanumeric
                return -1
            elif is_num2:
                return 1
            else:
                # Both alphanumeric, compare ASCII
                if ident1 != ident2:
                    return -1 if ident1 < ident2 else 1

        return 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        if self.major != other.major:
            return False
        if self.minor != other.minor:
            return False
        if self.patch != other.patch:
            return False
        if self._compare_prerelease(other.prerelease) != 0:
            return False
        # Build metadata is ignored for equality
        return True

    def __ne__(self, other):
        eq = self.__eq__(other)
        if eq is NotImplemented:
            return NotImplemented
        return not eq

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        if self.major < other.major:
            return True
        if self.major > other.major:
            return False
        if self.minor < other.minor:
            return True
        if self.minor > other.minor:
            return False
        if self.patch < other.patch:
            return True
        if self.patch > other.patch:
            return False
        return self._compare_prerelease(other.prerelease) < 0

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self == other or self < other

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return not (self < other or self == other)

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return not (self < other)

    def __hash__(self):
        # Build metadata ignored
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def bump(self, kind: str) -> 'Version':
        """
        Bump the version by 'major', 'minor', or 'patch'.
        Result never has prerelease or build.
        """
        if kind == 'major':
            return Version(self.major + 1, 0, 0)
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0)
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: '{kind}'")


def _parse_partial_version(spec: str) -> Version:
    """
    Parses a partial version for comparators.
    '1' -> '1.0.0'
    '1.2' -> '1.2.0'
    '1.2.3' -> '1.2.3'
    Raises ValueError if pre-release or build is present in partial version string.
    """
    # A partial version cannot have prerelease or build part according to the prompt.
    if '-' in spec or '+' in spec:
        raise ValueError(f"Partial version '{spec}' cannot contain pre-release or build")

    parts = spec.split('.')
    if not parts:
        raise ValueError(f"Invalid partial version: '{spec}'")

    try:
        if len(parts) == 1:
            if not parts[0].isdigit(): raise ValueError
            return Version(int(parts[0]), 0, 0)
        elif len(parts) == 2:
            if not parts[0].isdigit() or not parts[1].isdigit(): raise ValueError
            return Version(int(parts[0]), int(parts[1]), 0)
        elif len(parts) == 3:
            # This is a full version, let Version.parse handle it strictly
            return Version.parse(spec)
        else:
            raise ValueError(f"Invalid partial version format: '{spec}'")
    except ValueError:
        raise ValueError(f"Invalid partial version: '{spec}'")


def satisfies(version, spec: str) -> bool:
    """
    Check if a version satisfies a range specification.
    """
    if isinstance(version, str):
        version = Version.parse(version)
    elif not isinstance(version, Version):
        raise ValueError("Version must be a Version object or string")

    spec = spec.strip()
    if not spec:
        raise ValueError("Spec cannot be empty")

    # Split by whitespace
    comparators = spec.split()

    for comp in comparators:
        if not comp:
            continue

        op = ''
        ver_str = comp

        if comp.startswith('>='):
            op = '>='
            ver_str = comp[2:]
        elif comp.startswith('<='):
            op = '<='
            ver_str = comp[2:]
        elif comp.startswith('>'):
            op = '>'
            ver_str = comp[1:]
        elif comp.startswith('<'):
            op = '<'
            ver_str = comp[1:]
        elif comp.startswith('='):
            op = '='
            ver_str = comp[1:]
        elif comp.startswith('^'):
            op = '^'
            ver_str = comp[1:]
        elif comp.startswith('~'):
            op = '~'
            ver_str = comp[1:]
        else:
            op = '='
            # ver_str remains comp

        if not ver_str:
            raise ValueError(f"Invalid comparator: '{comp}'")

        # Parse the target version for the comparator
        try:
            target = _parse_partial_version(ver_str)
        except ValueError:
            raise ValueError(f"Invalid version in comparator '{comp}': {ver_str}")

        # Apply operator logic
        if op == '=':
            if version != target:
                return False
        elif op == '>=':
            if version < target:
                return False
        elif op == '>':
            if version <= target:
                return False
        elif op == '<=':
            if version > target:
                return False
        elif op == '<':
            if version >= target:
                return False
        elif op == '^':
            # Caret logic
            # >= target
            if version < target:
                return False

            # Calculate upper bound
            major, minor, patch = target.major, target.minor, target.patch

            if major > 0:
                # ^1.2.3 -> <2.0.0
                upper = Version(major + 1, 0, 0)
            elif minor > 0:
                # ^0.2.3 -> <0.3.0
                upper = Version(0, minor + 1, 0)
            else:
                # ^0.0.3 -> <0.0.4
                upper = Version(0, 0, patch + 1)

            if version >= upper:
                return False

        elif op == '~':
            # Tilde logic
            # >= target
            if version < target:
                return False

            major, minor, patch = target.major, target.minor, target.patch

            # Determine if original spec had a patch component
            # We passed partials to _parse_partial_version which filled in zeros.
            # But tilde behavior differs based on input precision.
            # ~1 -> >=1.0.0 <2.0.0
            # ~1.2 -> >=1.2.0 <1.3.0
            # ~1.2.3 -> >=1.2.3 <1.3.0

            # We need to know if the input ver_str had a patch.
            # Let's re-parse lightly to detect structure
            parts = ver_str.split('.')

            if len(parts) == 1:
                # ~1 -> <(major+1).0.0
                upper = Version(major + 1, 0, 0)
            else:
                # ~1.2 or ~1.2.3 -> <major.(minor+1).0
                upper = Version(major, minor + 1, 0)

            if version >= upper:
                return False

        else:
            raise ValueError(f"Unknown operator: {op}")

    return True
