import dataclasses
from typing import Any, Callable, Optional, Union


# Exceptions

class MachineError(Exception):
    """Base exception for the state machine."""
    pass


class InvalidTransition(MachineError):
    """Raised when no transition for the event leaves the current state."""

    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"No transition for event '{event}' from state '{state}'")


class GuardRejected(MachineError):
    """Raised when all transitions for the event from the current state are rejected by guards."""

    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"All transitions for event '{event}' from state '{state}' rejected by guards")


# Data Classes

@dataclasses.dataclass
class State:
    name: str
    on_enter: Optional[Callable] = None
    on_exit: Optional[Callable] = None


@dataclasses.dataclass
class Transition:
    event: str
    source: Union[str, list[str], tuple[str, ...]]
    target: Optional[Union[str, None]]
    guard: Optional[Callable] = None
    action: Optional[Callable] = None


@dataclasses.dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict


# Machine

class Machine:
    def __init__(
        self,
        states: list[Union[State, str]],
        transitions: list[Transition],
        initial: str,
        context: Any = None
    ):
        if not states:
            raise ValueError("States list must not be empty")

        self._states_map: dict[str, State] = {}
        for s in states:
            if isinstance(s, str):
                s = State(name=s)
            if not isinstance(s, State):
                raise ValueError(f"Invalid state definition: {s}")
            if s.name in self._states_map:
                raise ValueError(f"Duplicate state name: {s.name}")
            self._states_map[s.name] = s

        if initial not in self._states_map:
            raise ValueError(f"Initial state '{initial}' is not defined")

        self._transitions = list(transitions)  # Keep original order

        # Validate transition sources and targets
        valid_sources = {"*"} | set(self._states_map.keys())
        for t in self._transitions:
            # Check source
            if isinstance(t.source, str):
                sources = [t.source]
            elif isinstance(t.source, (list, tuple)):
                sources = list(t.source)
            else:
                raise ValueError(f"Invalid source type for transition: {t.source}")

            for src in sources:
                if src not in valid_sources:
                    raise ValueError(f"Transition references unknown source state: {src}")

            # Check target
            if t.target is not None:
                if t.target not in self._states_map:
                    raise ValueError(f"Transition references unknown target state: {t.target}")

        self._initial_state = initial
        self.state = initial
        self.context = context
        self.history: list[tuple[str, str, str]] = []

        self._listeners: list[Callable] = []
        self._is_firing = False

    def _get_matching_transitions(self, event: str, current_state: str) -> list[Transition]:
        matches = []
        for t in self._transitions:
            if t.event != event:
                continue

            # Check source match
            if isinstance(t.source, str):
                if t.source == "*" or t.source == current_state:
                    matches.append(t)
            elif isinstance(t.source, (list, tuple)):
                if current_state in t.source:
                    matches.append(t)
        return matches

    def fire(self, event: str, **data) -> str:
        if self._is_firing:
            raise MachineError("Cannot fire while a transition is already running")

        self._is_firing = True
        try:
            current_state = self.state
            candidates = self._get_matching_transitions(event, current_state)

            if not candidates:
                raise InvalidTransition(current_state, event)

            # Create the shared data dict
            event_data = dict(data)

            # Find the first transition that passes the guard (or has no guard)
            chosen_transition = None
            for t in candidates:
                if t.guard is None:
                    chosen_transition = t
                    break
                else:
                    # Build an Event object for the guard
                    # For guard evaluation, target is technically the potential target.
                    # Spec says: "One data dict holding the keyword arguments is created per call; every Event built during the call shares that same dict object"
                    # "guards are evaluated in candidate order..."
                    # Guard signature: hook(machine, event)

                    # Determine target for Event construction. 
                    # If internal (target=None), target is current_state.
                    # If normal, target is t.target.
                    target_for_event = t.target if t.target is not None else current_state

                    ev_obj = Event(
                        name=event,
                        source=current_state,
                        target=target_for_event,
                        data=event_data
                    )

                    if t.guard(self, ev_obj):
                        chosen_transition = t
                        break

            if chosen_transition is None:
                raise GuardRejected(current_state, event)

            # Execute the chosen transition
            t = chosen_transition
            source_state = current_state

            # Determine final target state name for history and state update
            if t.target is None:
                # Internal transition
                final_target_state = source_state
                is_internal = True
            else:
                final_target_state = t.target
                is_internal = False

            # Build the Event object for execution
            ev_obj = Event(
                name=event,
                source=source_state,
                target=final_target_state,
                data=event_data
            )

            if not is_internal:
                # 1. Current state's on_exit
                src_state_obj = self._states_map[source_state]
                if src_state_obj.on_exit:
                    src_state_obj.on_exit(self, ev_obj)

            # 2. Transition's action (runs for both internal and normal)
            if t.action:
                t.action(self, ev_obj)

            if not is_internal:
                # 3. Set state to target and append to history
                # State change happens here. 
                # Note: Spec says "If it comes from ... the action, the state and history are unchanged."
                # Since action ran successfully, we now update state.
                self.state = final_target_state
                self.history.append((source_state, event, final_target_state))

                # 4. Target state's on_enter
                tgt_state_obj = self._states_map[final_target_state]
                if tgt_state_obj.on_enter:
                    tgt_state_obj.on_enter(self, ev_obj)
            else:
                # Internal: record history, state unchanged
                self.history.append((source_state, event, source_state))

            # 5. Listeners (run for both types)
            # Spec: "then every listener ... called as listener(source, event, target)"
            # Spec: "If it comes from on_enter or a listener, the state has already changed."
            for listener in self._listeners:
                listener(source_state, event, final_target_state)

            return self.state

        finally:
            self._is_firing = False

    def can_fire(self, event: str, **data) -> bool:
        current_state = self.state
        candidates = self._get_matching_transitions(event, current_state)

        if not candidates:
            return False

        event_data = dict(data)

        for t in candidates:
            if t.guard is None:
                return True

            target_for_event = t.target if t.target is not None else current_state
            ev_obj = Event(
                name=event,
                source=current_state,
                target=target_for_event,
                data=event_data
            )

            if t.guard(self, ev_obj):
                return True

        return False

    def available_events(self) -> list[str]:
        current_state = self.state
        events = set()
        for t in self._transitions:
            if t.event in events:
                continue # Optimization

            if isinstance(t.source, str):
                if t.source == "*" or t.source == current_state:
                    events.add(t.event)
            elif isinstance(t.source, (list, tuple)):
                if current_state in t.source:
                    events.add(t.event)

        return sorted(list(events))

    def on_transition(self, listener: Callable):
        self._listeners.append(listener)

    def reset(self):
        self.state = self._initial_state
        self.history = []
