import fsm

class VendingError(Exception):
    pass

class SoldOut(VendingError):
    pass

class InsufficientCredit(VendingError):
    pass


class VendingMachine:
    ACCEPTED_COINS = {5, 10, 25, 100}
    COINS_LARGEST_FIRST = [100, 25, 10, 5]

    def __init__(self, products: dict[str, tuple[int, int]]):
        # products: dict[str, tuple[int, int]] -> code: (price, stock)
        self._inventory = {code: [price, stock] for code, (price, stock) in products.items()}
        self._credit = 0
        self._sales = {}  # code: qty_sold
        self._revenue = 0
        self._last_change = []

        # Define States
        idle = fsm.State('idle')
        credit = fsm.State('credit')
        maintenance = fsm.State('maintenance')
        states = [idle, credit, maintenance]

        # Define Transitions
        # Actions are defined below
        transitions = [
            # insert: idle -> credit, credit -> credit
            fsm.Transition('insert', 'idle', 'credit', action=self._action_insert),
            fsm.Transition('insert', 'credit', 'credit', action=self._action_insert),

            # select: credit -> idle
            fsm.Transition('select', 'credit', 'idle', action=self._action_select),

            # cancel: credit -> idle
            fsm.Transition('cancel', 'credit', 'idle', action=self._action_cancel),

            # service: idle -> maintenance
            fsm.Transition('service', 'idle', 'maintenance', action=None),

            # restock: maintenance -> maintenance
            fsm.Transition('restock', 'maintenance', 'maintenance', action=self._action_restock),

            # resume: maintenance -> idle
            fsm.Transition('resume', 'maintenance', 'idle', action=None),
        ]

        self.machine = fsm.Machine(states, transitions, initial='idle', context=self)

    # --- Internal Actions (Hooks) ---

    def _action_insert(self, machine, event):
        coin = event.data['coin']
        self._credit += coin

    def _action_select(self, machine, event):
        code = event.data['code']
        price, stock = self._inventory[code]

        # Update Inventory and Stats
        self._inventory[code][1] -= 1
        self._sales[code] = self._sales.get(code, 0) + 1
        self._revenue += price

        # Calculate Change
        change_amount = self._credit - price
        self._last_change = self._calculate_change(change_amount)

        # Reset Credit
        self._credit = 0

    def _action_cancel(self, machine, event):
        self._last_change = self._calculate_change(self._credit)
        self._credit = 0

    def _action_restock(self, machine, event):
        code = event.data['code']
        qty = event.data['qty']
        price = event.data.get('price')

        if code not in self._inventory:
            # Price is guaranteed to be present by validation in method, but double check
            if price is None:
                raise KeyError(f"Price required for new code {code}")
            self._inventory[code] = [price, qty]
        else:
            self._inventory[code][1] += qty
            if price is not None:
                self._inventory[code][0] = price

    # --- Helpers ---

    def _calculate_change(self, amount):
        change = []
        for coin in self.COINS_LARGEST_FIRST:
            while amount >= coin:
                change.append(coin)
                amount -= coin
        return change

    # --- Public Methods ---

    def insert(self, coin: int) -> int:
        if coin not in self.ACCEPTED_COINS:
            raise ValueError(f"Coin {coin} is not accepted")

        self.machine.fire('insert', coin=coin)
        return self._credit

    def select(self, code: str) -> list[int]:
        # State check is handled by FSM fire (raises InvalidTransition if not in 'credit')
        # But we need specific errors for Code/Stock/Credit which might be more descriptive 
        # if we check before, or let action raise them.
        # Spec: "Check order: State ... Code ... Stock ... Credit ..."
        # If I check in method, I avoid firing if invalid.

        if code not in self._inventory:
            raise KeyError(code)

        price, stock = self._inventory[code]

        if stock <= 0:
            raise SoldOut(f"Code {code} is sold out")

        if self._credit < price:
            raise InsufficientCredit(f"Credit {self._credit} < Price {price}")

        self.machine.fire('select', code=code)
        return self._last_change

    def cancel(self) -> list[int]:
        self.machine.fire('cancel')
        return self._last_change

    def service(self) -> None:
        self.machine.fire('service')

    def restock(self, code: str, qty: int, price: int | None = None) -> None:
        if qty < 1:
            raise ValueError("Quantity must be >= 1")

        if code not in self._inventory and price is None:
            raise KeyError(f"Price required for new code {code}")

        self.machine.fire('restock', code=code, qty=qty, price=price)

    def resume(self) -> None:
        self.machine.fire('resume')

    # --- Properties ---

    @property
    def state(self) -> str:
        return self.machine.state

    @property
    def credit(self) -> int:
        return self._credit

    def stock(self, code: str) -> int:
        if code not in self._inventory:
            raise KeyError(code)
        return self._inventory[code][1]

    def price(self, code: str) -> int:
        if code not in self._inventory:
            raise KeyError(code)
        return self._inventory[code][0]

    def sales(self) -> dict[str, int]:
        return self._sales.copy()

    @property
    def revenue(self) -> int:
        return self._revenue
