# library/loans.py
"""
Loan processing, holds, and fines for the library lending system.
"""

from dataclasses import dataclass, field
from datetime import date, timedelta

from library.catalog import Catalog, Member
from library.fines import (
    POLICY,
    HOLD_PICKUP_DAYS,
    due_date,
    fine_for,
)


class LoanError(Exception):
    """Base exception for loan operations."""


class Blocked(LoanError):
    """Member is blocked due to unpaid fines."""


class DuplicateLoan(LoanError):
    """Member already has a loan or hold for this book."""


class LimitReached(LoanError):
    """Member has reached their loan limit."""


class NotAvailable(LoanError):
    """No copies are available for checkout."""


class RenewalRefused(LoanError):
    """Renewal request was refused."""


@dataclass
class Loan:
    """Represents a single loan transaction."""

    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: date | None = None
    fine: int = 0


class _Hold:
    """Internal representation of a hold in the queue."""

    def __init__(self, member_id: str):
        self.member_id = member_id
        self.status: str = "waiting"  # 'waiting' or 'ready'
        self.deadline: date | None = None


class Library:
    """Core lending logic for the library."""

    def __init__(self, catalog: Catalog, clock):
        self.catalog = catalog
        self.clock = clock
        self._loans: dict[int, Loan] = {}
        self._next_loan_id = 1
        self._balances: dict[str, int] = {}  # member_id -> cents
        # isbn -> list of _Hold
        self._hold_queues: dict[str, list[_Hold]] = {}
        self._last_processed_date: date | None = None

    def _today(self) -> date:
        """Get current date and advance internal state if necessary."""
        today = self.clock()
        self._advance_time(today)
        return today

    def _advance_time(self, today: date) -> None:
        """Process hold expiries up to 'today'."""
        if self._last_processed_date is None:
            self._last_processed_date = today
            return

        if today <= self._last_processed_date:
            return

        # Process each day strictly after the last processed date up to today
        current = self._last_processed_date + timedelta(days=1)
        while current <= today:
            for isbn, queue in self._hold_queues.items():
                # Iterate backwards to safely remove/expired items
                for hold in list(queue):
                    if hold.status == "ready" and hold.deadline is not None:
                        if current > hold.deadline:
                            # Expire this hold
                            queue.remove(hold)
                            # Try to promote the next waiting hold
                            self._try_promote_next(isbn, current)
            self._last_processed_date = current
            current += timedelta(days=1)

    def _try_promote_next(self, isbn: str, on_date: date) -> None:
        """Set aside a copy for the earliest waiting hold in the queue."""
        queue = self._hold_queues.get(isbn, [])
        for hold in queue:
            if hold.status == "waiting":
                hold.status = "ready"
                hold.deadline = due_date(on_date, HOLD_PICKUP_DAYS)
                break

    def available(self, isbn: str) -> int:
        """Return number of copies available for checkout."""
        self._today()  # Ensure time is up-to-date
        book = self.catalog.book(isbn)
        active_loans = sum(
            1
            for loan in self._loans.values()
            if loan.isbn == isbn and loan.returned is None
        )
        ready_holds = sum(
            1
            for hold in self._hold_queues.get(isbn, [])
            if hold.status == "ready"
        )
        return book.copies - active_loans - ready_holds

    def _get_active_loans(self, member_id: str) -> list[Loan]:
        return [
            loan
            for loan in self._loans.values()
            if loan.member_id == member_id and loan.returned is None
        ]

    def _has_active_loan(self, member_id: str, isbn: str) -> bool:
        return any(
            loan.isbn == isbn
            for loan in self._get_active_loans(member_id)
        )

    def _get_hold_status(self, member_id: str, isbn: str) -> _Hold | None:
        queue = self._hold_queues.get(isbn, [])
        for hold in queue:
            if hold.member_id == member_id:
                return hold
        return None

    def checkout(self, member_id: str, isbn: str) -> Loan:
        """Check out a book."""
        today = self._today()
        member = self.catalog.member(member_id)
        policy = POLICY[member.kind]

        # 1. Check Balance
        if self.balance(member_id) > 0:
            raise Blocked("Member has outstanding fines.")

        # 2. Check Duplicate Loan
        if self._has_active_loan(member_id, isbn):
            raise DuplicateLoan("Member already has a loan for this book.")

        # 3. Check Loan Limit
        active_loans = self._get_active_loans(member_id)
        if len(active_loans) >= policy.max_loans:
            raise LimitReached("Member has reached their loan limit.")

        # 4. Handle Holds
        hold = self._get_hold_status(member_id, isbn)
        if hold is not None and hold.status == "ready":
            # Use the ready hold's copy. Remove the hold.
            self._hold_queues[isbn].remove(hold)
            # available count effectively stays same (ready_hold -1, loan +1) so no need to check avail
        else:
            # Check availability
            if self.available(isbn) <= 0:
                raise NotAvailable("No copies available.")
            # If we are here, we are taking a regular available copy.
            # If the member has a *waiting* hold, it gets cancelled implicitly?
            # Spec: "A successful checkout also removes the member's waiting hold on the isbn, if any."
            if hold is not None and hold.status == "waiting":
                self._hold_queues[isbn].remove(hold)

        # Create Loan
        due = due_date(today, policy.loan_days)
        loan = Loan(
            loan_id=self._next_loan_id,
            member_id=member_id,
            isbn=isbn,
            start=today,
            due=due,
        )
        self._loans[self._next_loan_id] = loan
        self._next_loan_id += 1
        return loan

    def place_hold(self, member_id: str, isbn: str) -> int:
        """Place a hold on a book."""
        self._today()  # Update time
        self.catalog.member(member_id)  # Validate member exists
        self.catalog.book(isbn)  # Validate book exists

        if self._has_active_loan(member_id, isbn):
            raise DuplicateLoan("Member already has a loan for this book.")

        if self._get_hold_status(member_id, isbn) is not None:
            raise DuplicateLoan("Member already has a hold for this book.")

        if self.available(isbn) > 0:
            raise LoanError("Book is currently available; no hold needed.")

        if isbn not in self._hold_queues:
            self._hold_queues[isbn] = []

        hold = _Hold(member_id)
        self._hold_queues[isbn].append(hold)
        return len(self._hold_queues[isbn])

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        """Cancel a hold."""
        today = self._today()
        queue = self._hold_queues.get(isbn)
        if not queue:
            raise KeyError("No hold found for this member and ISBN.")

        hold = self._get_hold_status(member_id, isbn)
        if hold is None:
            raise KeyError("No hold found for this member and ISBN.")

        queue.remove(hold)

        # If it was ready, its copy is now "freed". Pass to next waiting hold.
        if hold.status == "ready":
            self._try_promote_next(isbn, today)

    def holds(self, isbn: str) -> list[str]:
        """Return list of member IDs in the hold queue for this ISBN."""
        self._today()
        queue = self._hold_queues.get(isbn, [])
        return [h.member_id for h in queue]

    def hold_status(self, member_id: str, isbn: str) -> tuple[str, date | int]:
        """Return status of a hold."""
        self._today()
        hold = self._get_hold_status(member_id, isbn)
        if hold is None:
            raise KeyError("No hold found.")

        if hold.status == "ready":
            return ("ready", hold.deadline)
        else:
            # Position is 1-based in the queue
            queue = self._hold_queues[isbn]
            for i, h in enumerate(queue):
                if h.member_id == member_id:
                    return ("waiting", i + 1)

        # Should not reach here
        raise KeyError("No hold found.")

    def renew(self, loan_id: int) -> date:
        """Renew a loan."""
        today = self._today()
        loan = self._loans.get(loan_id)
        if loan is None:
            raise KeyError("Loan not found.")

        if loan.returned is not None:
            raise LoanError("Loan already returned.")

        # If overdue
        if today > loan.due:
            raise RenewalRefused("Loan is overdue.")

        member = self.catalog.member(loan.member_id)
        policy = POLICY[member.kind]

        # Check if ISBN has any hold
        if self._hold_queues.get(loan.isbn):
            raise RenewalRefused("Another member is waiting for this book.")

        # Check renewal limit
        if loan.renewals >= policy.renewals:
            raise RenewalRefused("Renewal limit reached.")

        new_due = due_date(loan.due, policy.loan_days)
        loan.due = new_due
        loan.renewals += 1
        return new_due

    def checkin(self, loan_id: int) -> int:
        """Check in a loan and calculate fines."""
        today = self._today()
        loan = self._loans.get(loan_id)
        if loan is None:
            raise KeyError("Loan not found.")

        if loan.returned is not None:
            raise LoanError("Loan already returned.")

        loan.returned = today

        member = self.catalog.member(loan.member_id)
        fine = fine_for(member.kind, loan.due, today)
        loan.fine = fine

        if fine > 0:
            current_balance = self._balances.get(member.member_id, 0)
            self._balances[member.member_id] = current_balance + fine

        # Set aside copy for next waiting hold if any
        queue = self._hold_queues.get(loan.isbn, [])
        has_waiting = any(h.status == "waiting" for h in queue)
        if has_waiting:
            self._try_promote_next(loan.isbn, today)

        return fine

    def accrued_fine(self, loan_id: int) -> int:
        """Calculate fine if returned today."""
        today = self._today()
        loan = self._loans.get(loan_id)
        if loan is None:
            raise KeyError("Loan not found.")

        if loan.returned is not None:
            return loan.fine

        member = self.catalog.member(loan.member_id)
        return fine_for(member.kind, loan.due, today)

    def balance(self, member_id: str) -> int:
        """Get member's outstanding fine balance."""
        self.catalog.member(member_id)  # Validate member
        return self._balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        """Pay down fines."""
        self.catalog.member(member_id)  # Validate member
        balance = self.balance(member_id)

        if amount <= 0:
            raise ValueError("Payment amount must be positive.")
        if amount > balance:
            raise ValueError("Payment amount exceeds balance.")

        new_balance = balance - amount
        self._balances[member_id] = new_balance
        return new_balance

    def loans(self, member_id: str) -> list[Loan]:
        """Get active loans for a member, sorted by due date then ID."""
        self.catalog.member(member_id)  # Validate member
        active = self._get_active_loans(member_id)
        active.sort(key=lambda l: (l.due, l.loan_id))
        return active

    def overdue(self) -> list[Loan]:
        """Get all overdue active loans, sorted by due date then ID."""
        today = self._today()
        overdue_loans = [
            loan
            for loan in self._loans.values()
            if loan.returned is None and loan.due < today
        ]
        overdue_loans.sort(key=lambda l: (l.due, l.loan_id))
        return overdue_loans
