class ErrorValue(str):
    """Represents an error value in a cell."""
    def __new__(cls, value):
        return super().__new__(cls, value)

    def __eq__(self, other):
        if isinstance(other, ErrorValue):
            return str.__eq__(self, other)
        if isinstance(other, str):
            return str.__eq__(self, other)
        return False

    def __hash__(self):
        return str.__hash__(self)


ERROR_VALUE = ErrorValue("#ERROR!")
CYCLE_VALUE = ErrorValue("#CYCLE!")

# AST Nodes
class Node:
    pass

class NumNode(Node):
    def __init__(self, value):
        self.value = value # int or float

class RefNode(Node):
    def __init__(self, name):
        self.name = name # upper case string

class UnaryOpNode(Node):
    def __init__(self, op, operand):
        self.op = op # '+' or '-'
        self.operand = operand

class BinOpNode(Node):
    def __init__(self, op, left, right):
        self.op = op # '+', '-', '*', '/'
        self.left = left
        self.right = right


def parse_formula(source: str):
    if not source or not source.startswith("="):
        raise FormulaError("Formula must start with =")

    text = source[1:]
    tokens = tokenize(text)
    ast = parse_expr(tokens)
    if tokens:
        raise FormulaError("Unexpected characters at end of formula")
    return ast


def tokenize(text):
    import re
    # Tokenize: numbers, refs, operators, parens
    # number: digits [. digits]
    # ref: letters digits
    # op: + - * / ( )

    tokens = []
    i = 0
    n = len(text)
    while i < n:
        if text[i].isspace():
            i += 1
            continue

        # Check for ref or number
        # Ref: letters followed by digits
        # Number: digits [. digits]

        if text[i].isalpha():
            j = i
            while j < n and text[j].isalpha():
                j += 1
            # Must be followed by digits for a ref
            if j < n and text[j].isdigit():
                k = j
                while k < n and text[k].isdigit():
                    k += 1
                ref_str = text[i:k].upper()
                if not is_valid_ref(ref_str):
                    raise FormulaError(f"Invalid reference: {ref_str}")
                tokens.append(("REF", ref_str))
                i = k
                continue
            else:
                raise FormulaError(f"Invalid reference: {text[i:j]}")
        elif text[i].isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            if j < n and text[j] == '.':
                j += 1
                if j >= n or not text[j].isdigit():
                     # Allow trailing dot? Spec: digits [. digits]. Usually implies digits after dot if present.
                     # "no sign, no exponent". 
                     # If it is just digits, it's int. If digits.digits, float.
                     # If digits. then it might be invalid or int? Let's assume digits required after dot if dot present.
                     # However, standard number parsing often allows trailing dot as integer or float.
                     # Let's look at spec: "digits [. digits]". This usually means optional dot and optional digits? 
                     # Or is it [digits] then optional [. digits]? 
                     # "digits [. digits]" suggests 1 or more digits, then optionally dot and 1 or more digits?
                     # If just "1." it might be valid float. But "digits" implies >0 digits.
                     # Let's enforce at least one digit after dot if dot is present, or treat as float if dot present.
                     # Actually, let's look at regex approach mentally.
                     # If we have 1.2, j moves to 3.
                     # If we have 1., text[j]=='.' then j++ then text[j] not digit. Raise error?
                     # Let's assume standard: 1.5 is float. 1 is int. 1. is likely invalid or 1.0.
                     # To be safe with spec "digits [. digits]", if dot is present, there must be digits after.
                     if not text[j-1].isdigit():
                         raise FormulaError("Invalid number format")

                    # Re-read spec: number := digits [. digits]
                    # This implies [dot digits] is optional. If dot is present, digits after dot are required?
                    # Usually yes. "1." is often not valid. "1.0" is valid.
                    # Let's stick to: if dot found, must be followed by at least one digit.
                    raise FormulaError("Invalid number format")

            num_str = text[i:j]
            if '.' in num_str:
                val = float(num_str)
            else:
                val = int(num_str)
            tokens.append(("NUM", val))
            i = j
            continue
        elif text[i] in "+-*/()":
            tokens.append(("OP", text[i]))
            i += 1
            continue
        else:
            raise FormulaError(f"Unexpected character: {text[i]}")

    return tokens


def is_valid_ref(ref):
    # ref is uppercase, e.g. A1, B10, Z999
    if not ref:
        return False
    i = 0
    while i < len(ref) and ref[i].isalpha():
        i += 1

    cols = ref[:i]
    rows = ref[i:]

    if not rows:
        return False
    if not cols:
        return False

    # Single letter column A-Z
    if len(cols) != 1:
        return False

    # Row 1-999, no leading zeros
    if rows.startswith('0'):
        return False

    try:
        row_num = int(rows)
    except ValueError:
        return False

    if 1 <= row_num <= 999:
        return True

    return False


def parse_expr(tokens):
    node = parse_term(tokens)
    while tokens and tokens[0][0] == "OP" and tokens[0][1] in "+-":
        op = tokens.pop(0)[1]
        right = parse_term(tokens)
        node = BinOpNode(op, node, right)
    return node


def parse_term(tokens):
    node = parse_unary(tokens)
    while tokens and tokens[0][0] == "OP" and tokens[0][1] in "*/":
        op = tokens.pop(0)[1]
        right = parse_unary(tokens)
        node = BinOpNode(op, node, right)
    return node


def parse_unary(tokens):
    if not tokens:
        raise FormulaError("Unexpected end of formula")

    if tokens[0][0] == "OP" and tokens[0][1] in "+-":
        op = tokens.pop(0)[1]
        operand = parse_unary(tokens)
        return UnaryOpNode(op, operand)

    return parse_primary(tokens)


def parse_primary(tokens):
    if not tokens:
        raise FormulaError("Unexpected end of formula")

    token = tokens[0]
    if token[0] == "NUM":
        return NumNode(tokens.pop(0)[1])

    if token[0] == "REF":
        return RefNode(tokens.pop(0)[1])

    if token[0] == "OP" and token[1] == '(':
        tokens.pop(0)
        expr = parse_expr(tokens)
        if not tokens or tokens[0][1] != ')':
            raise FormulaError("Missing closing parenthesis")
        tokens.pop(0)
        return expr

    raise FormulaError(f"Unexpected token: {token}")


def references(tree):
    refs = set()
    def traverse(node):
        if isinstance(node, RefNode):
            refs.add(node.name)
        elif isinstance(node, UnaryOpNode):
            traverse(node.operand)
        elif isinstance(node, BinOpNode):
            traverse(node.left)
            traverse(node.right)

    traverse(tree)
    return refs


def evaluate(tree, lookup):
    if isinstance(tree, NumNode):
        return tree.value

    if isinstance(tree, RefNode):
        val = lookup(tree.name)
        if val is None:
            return 0
        return val

    if isinstance(tree, UnaryOpNode):
        operand = evaluate(tree.operand, lookup)

        # Propagate errors
        if isinstance(operand, ErrorValue):
            return operand

        # Check for text
        if isinstance(operand, str):
            return ERROR_VALUE

        # operand is int or float
        if tree.op == '-':
            return -operand
        else: # '+'
            return operand

    if isinstance(tree, BinOpNode):
        left = evaluate(tree.left, lookup)
        right = evaluate(tree.right, lookup)

        # Propagate errors
        if isinstance(left, ErrorValue):
            return left
        if isinstance(right, ErrorValue):
            return right

        # Check for text
        if isinstance(left, str) or isinstance(right, str):
            return ERROR_VALUE

        # Must be numeric here (int or float)
        op = tree.op

        try:
            if op == '+':
                res = left + right
                if isinstance(left, float) or isinstance(right, float):
                    return float(res)
                return int(res)

            elif op == '-':
                res = left - right
                if isinstance(left, float) or isinstance(right, float):
                    return float(res)
                return int(res)

            elif op == '*':
                res = left * right
                if isinstance(left, float) or isinstance(right, float):
                    return float(res)
                return int(res)

            elif op == '/':
                if right == 0:
                    return ERROR_VALUE
                return float(left / right)

        except Exception:
            return ERROR_VALUE

    raise FormulaError("Unknown node type")
