class DependencyGraph:
    def __init__(self):
        # Maps cell -> set of cells it depends on (precedents)
        self._precedents = {}
        # Maps cell -> set of cells that depend on it (dependents)
        self._dependents = {}

    def set_dependencies(self, cell: str, precedents: iter):
        """Replace the precedents of `cell` with the given iterable."""
        new_precedents = set(precedents)

        # Remove old reverse edges
        old_precedents = self._precedents.get(cell, set())
        for old_p in old_precedents:
            if cell in self._dependents.get(old_p, set()):
                self._dependents[old_p].discard(cell)

        # Set new precedents
        if new_precedents:
            self._precedents[cell] = new_precedents
        elif cell in self._precedents:
            del self._precedents[cell]
            # Ensure empty set is removed from precedents to keep it clean, 
            # though get handles missing keys

        # Add new reverse edges
        for p in new_precedents:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

    def precedents(self, cell: str) -> set:
        """Return the direct precedents of `cell`."""
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell: str) -> set:
        """Return the direct dependents of `cell`."""
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell: str) -> set:
        """Return all transitive dependents of `cell`."""
        # BFS/DFS to find all cells reachable via dependents edges
        visited = set()
        stack = list(self._dependents.get(cell, set()))

        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)

            # Add dependents of current
            next_deps = self._dependents.get(current, set())
            for d in next_deps:
                if d not in visited:
                    stack.append(d)

        # If cell is in the visited set, it's part of a cycle involving cell
        # or a path leading back to cell. The spec says: "If `cell` is on a cycle, include `cell` itself."
        # Since we start from direct dependents, if we reach `cell`, it means there's a cycle.
        if cell in visited:
            visited.add(cell)

        return visited

    def cycle_cells(self) -> set:
        """Return every cell that lies on a cycle."""
        # A cell is on a cycle if it is in an SCC of size > 1 or has a self-loop.
        # We can find all nodes that can reach themselves.
        # Using a DFS-based approach to find nodes in cycles.

        # Strategy: Find all Strongly Connected Components (SCCs) using Kosaraju's algorithm
        # or simply check reachability for nodes involved in the graph.
        # Given potential size, Kosaraju is O(V+E).

        # 1. Order nodes by finish time of DFS on graph (edges cell -> precedent)
        #    Note: My graph edges for "following precedents" are cell -> precedent.
        #    A cycle is a path cell -> ... -> cell.

        # Let's use a simpler DFS approach to find nodes that are part of cycles.
        # We can use Tarjan's or Kosaraju. Let's do Kosaraju.

        # Graph G: edges u -> v if u depends on v (u has v as precedent)
        # We want to find nodes in cycles in G.

        nodes = set(self._precedents.keys())
        for deps in self._dependents.values():
            nodes.update(deps)

        # Build adjacency list for G (cell -> precedents)
        adj = {n: self._precedents.get(n, set()) for n in nodes}

        # Kosaraju Step 1: Compute finish order on G
        visited = set()
        stack = []

        def dfs_visit(v):
            visited.add(v)
            for neighbor in adj[v]:
                if neighbor not in visited:
                    dfs_visit(neighbor)
            stack.append(v)

        for v in nodes:
            if v not in visited:
                dfs_visit(v)

        # Build reverse graph G^T: edges v -> u if u depends on v (v is dependent of u)
        # adj_t[v] = set of cells that depend on v (i.e. dependents)
        adj_t = {n: self._dependents.get(n, set()) for n in nodes}

        # Kosaraju Step 2: Process in reverse finish order on G^T
        sccs = []
        visited = set()

        def dfs_visit_t(v, component):
            visited.add(v)
            component.append(v)
            for neighbor in adj_t[v]:
                if neighbor not in visited:
                    dfs_visit_t(neighbor, component)

        while stack:
            v = stack.pop()
            if v not in visited:
                component = []
                dfs_visit_t(v, component)
                sccs.append(component)

        cycle_nodes = set()
        for component in sccs:
            if len(component) > 1:
                cycle_nodes.update(component)
            elif len(component) == 1:
                # Check for self-loop
                v = component[0]
                if v in adj[v]: # v depends on v
                    cycle_nodes.add(v)

        return cycle_nodes
