import re

# --- AST Classes ---

class Node:
    pass

class Number(Node):
    def __init__(self, value):
        self.value = value

class Ref(Node):
    def __init__(self, name):
        self.name = name.upper()

class UnaryOp(Node):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand

class BinOp(Node):
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right

# --- Exceptions and Error Values ---

class FormulaError(ValueError):
    pass

class ErrorValue(str):
    """Error values that compare equal to their text representation."""
    def __new__(cls, text):
        return super().__new__(cls, text)

    def __init__(self, text):
        # str.__init__ doesn't take extra args in py3, but text is passed to new
        pass

# Singleton instances for errors
ERROR_VAL = ErrorValue("#ERROR!")
CYCLE_VAL = ErrorValue("#CYCLE!")

# --- Lexer ---

TOKEN_REGEX = re.compile(r'''
    (?P<NUMBER>\d+(?:\.\d+)?)   | 
    (?P<REF>[A-Za-z]+\d+)      | 
    (?P<OP>[+\-*/])              | 
    (?P<PAREN>[(]|[)])
''', re.VERBOSE)

def _tokenize(source):
    """Generate tokens from source string. Raises FormulaError on invalid char."""
    tokens = []
    pos = 0
    while pos < len(source):
        if source[pos].isspace():
            pos += 1
            continue
        match = TOKEN_REGEX.match(source, pos)
        if not match:
            raise FormulaError(f"Invalid character '{source[pos]}' at position {pos}")
        pos = match.end()
        kind = match.lastgroup
        value = match.group()
        tokens.append((kind, value))
    return tokens

# --- Parser ---

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, kind=None, value=None):
        token = self.peek()
        if token is None:
            raise FormulaError("Unexpected end of input")
        if kind and token[0] != kind:
            raise FormulaError(f"Expected token type {kind}, got {token[0]}")
        if value and token[1] != value:
            raise FormulaError(f"Expected value '{value}', got '{token[1]}'")
        self.pos += 1
        return token

    def parse(self):
        if not self.tokens:
            raise FormulaError("Empty input")
        tree = self.parse_expr()
        if self.pos != len(self.tokens):
            raise FormulaError(f"Unexpected token '{self.tokens[self.pos][1]}'")
        return tree

    def parse_expr(self):
        left = self.parse_term()
        while self.peek() and self.peek()[0] == 'OP' and self.peek()[1] in '+-':
            op_token = self.consume('OP')
            right = self.parse_term()
            left = BinOp(op_token[1], left, right)
        return left

    def parse_term(self):
        left = self.parse_unary()
        while self.peek() and self.peek()[0] == 'OP' and self.peek()[1] in '*/':
            op_token = self.consume('OP')
            right = self.parse_unary()
            left = BinOp(op_token[1], left, right)
        return left

    def parse_unary(self):
        token = self.peek()
        if token and token[0] == 'OP' and token[1] in '+-':
            self.consume('OP')
            operand = self.parse_unary()
            return UnaryOp(token[1], operand)
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()
        if token is None:
            raise FormulaError("Unexpected end of input")

        if token[0] == 'PAREN' and token[1] == '(':
            self.consume('PAREN', '(')
            expr = self.parse_expr()
            self.consume('PAREN', ')')
            return expr

        if token[0] == 'NUMBER':
            self.consume('NUMBER')
            val_str = token[1]
            if '.' in val_str:
                return Number(float(val_str))
            else:
                return Number(int(val_str))

        if token[0] == 'REF':
            self.consume('REF')
            return Ref(self._validate_and_normalize_ref(token[1]))

        raise FormulaError(f"Unexpected token '{token[1]}'")

    def _validate_and_normalize_ref(self, ref_str):
        """Validate reference format and normalize to uppercase."""
        # Grammar: letters digits
        match = re.match(r'^([A-Za-z]+)(\d+)$', ref_str)
        if not match:
            raise FormulaError(f"Invalid reference format: {ref_str}")

        letters, digits = match.groups()

        # Case-insensitive, return uppercase
        name = letters.upper() + digits

        # Validate column (A-Z)
        if len(letters) > 1:
             raise FormulaError(f"Reference column too long: {ref_str}")

        col = letters.upper()
        if not ('A' <= col <= 'Z'):
            raise FormulaError(f"Invalid column: {ref_str}")

        # Validate row
        # Row must be 1-999, no leading zeros
        if digits.startswith('0') and len(digits) > 1:
            raise FormulaError(f"Leading zero in row: {ref_str}")

        row_num = int(digits)
        if row_num < 1 or row_num > 999:
            raise FormulaError(f"Row out of range: {ref_str}")

        return name

# --- Public API ---

def parse_formula(source: str):
    """Parse formula string (without '=') into AST."""
    if not source:
        raise FormulaError("Empty formula")
    try:
        tokens = _tokenize(source)
    except re.error as e:
        raise FormulaError(str(e))
    parser = Parser(tokens)
    return parser.parse()

def references(tree):
    """Return set of upper-case cell names referenced in the AST."""
    refs = set()

    def walk(node):
        if isinstance(node, Ref):
            refs.add(node.name)
        elif isinstance(node, UnaryOp):
            walk(node.operand)
        elif isinstance(node, BinOp):
            walk(node.left)
            walk(node.right)

    walk(tree)
    return refs

def evaluate(tree, lookup):
    """Evaluate AST given a lookup function."""

    def eval_node(node):
        if isinstance(node, Number):
            return node.value

        if isinstance(node, Ref):
            val = lookup(node.name)
            if val is None:
                return 0
            return val

        if isinstance(node, UnaryOp):
            operand = eval_node(node.operand)
            if isinstance(operand, ErrorValue):
                return operand
            if isinstance(operand, str):
                return ERROR_VAL
            if node.op == '-':
                return -operand
            elif node.op == '+':
                return operand

        if isinstance(node, BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)

            # Error propagation: left error takes precedence if both
            if isinstance(left, ErrorValue):
                return left
            if isinstance(right, ErrorValue):
                return right

            # Type checks for operations
            # If any operand is string (not error), it's an error
            if isinstance(left, str) or isinstance(right, str):
                return ERROR_VAL

            # Determine if result should be int or float
            # Float if either is float. Int/Int -> Int (except division)

            is_float = isinstance(left, float) or isinstance(right, float)

            if node.op == '+':
                res = left + right
            elif node.op == '-':
                res = left - right
            elif node.op == '*':
                res = left * right
            elif node.op == '/':
                if right == 0:
                    return ERROR_VAL
                res = left / right
                return float(res)

            # Type coercion for +, -, *
            if is_float:
                return float(res)
            else:
                return int(res)

        raise FormulaError(f"Unknown node type: {type(node)}")

    return eval_node(tree)
