"""Dependency graph for the sheet."""
from collections import deque
from typing import Iterable


class DependencyGraph:
    """Tracks which cells depend on which others."""

    def __init__(self) -> None:
        # cell -> set of cells it depends on (precedents)
        self._precedents: dict[str, set[str]] = {}
        # cell -> set of cells that depend on it (dependents)
        self._dependents: dict[str, set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]) -> None:
        """Set the cells that *cell* depends on."""
        old = self._precedents.get(cell, set())
        new = set(precedents)

        # Remove old reverse links
        for p in old:
            if p in self._dependents:
                self._dependents[p].discard(cell)
                if not self._dependents[p]:
                    del self._dependents[p]

        # Add new reverse links
        for p in new:
            self._dependents.setdefault(p, set()).add(cell)

        # Store new precedents
        if new:
            self._precedents[cell] = new
        else:
            self._precedents.pop(cell, None)
            # Clean up empty dependent entries
            for p in old:
                 if p in self._dependents and not self._dependents[p]:
                     del self._dependents[p]

    def precedents(self, cell: str) -> set[str]:
        """Return the direct precedents of *cell*."""
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell: str) -> set[str]:
        """Return the direct dependents of *cell*."""
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell: str) -> set[str]:
        """Return all cells that depend on *cell*, directly or transitively."""
        result: set[str] = set()
        queue: deque[str] = deque([cell])
        while queue:
            current = queue.popleft()
            direct = self._dependents.get(current)
            if not direct:
                continue
            for d in direct:
                if d not in result:
                    result.add(d)
                    queue.append(d)
        # Include cell itself if it is on a cycle (i.e., reachable from itself)
        if cell in result:
            result.add(cell)
        return result

    def cycle_cells(self) -> set[str]:
        """Return all cells that lie on at least one dependency cycle."""
        # Use iterative Tarjan's algorithm to find SCCs
        index_counter = [0]
        stack: list[str] = []
        on_stack: set[str] = set()
        lowlinks: dict[str, int] = {}
        index: dict[str, int] = {}
        sccs: list[list[str]] = []

        def strongconnect(node: str) -> None:
            index[node] = index_counter[0]
            lowlinks[node] = index_counter[0]
            index_counter[0] += 1
            stack.append(node)
            on_stack.add(node)

            for successor in self._precedents.get(node, set()):
                if successor not in index:
                    strongconnect(successor)
                    lowlinks[node] = min(lowlinks[node], lowlinks[successor])
                elif successor in on_stack:
                    lowlinks[node] = min(lowlinks[node], index[successor])

            if lowlinks[node] == index[node]:
                component: list[str] = []
                while True:
                    successor = stack.pop()
                    on_stack.discard(successor)
                    component.append(successor)
                    if successor == node:
                        break
                if len(component) > 1 or (len(component) == 1 and component[0] in self._precedents.get(component[0], set())):
                    sccs.append(component)

        # Run for all nodes in the graph
        all_nodes = set(self._precedents.keys()) | set(self._dependents.keys())
        for node in all_nodes:
            if node not in index:
                strongconnect(node)

        result: set[str] = set()
        for component in sccs:
            result.update(component)
        return result

