from __future__ import annotations

from .versions import Version, Range


class PackageIndex:
    """A database of available package releases and their dependencies."""

    def __init__(self) -> None:
        # Structure: {name: {Version: {dep_name: Range}}}
        self._data: dict[str, dict[Version, dict[str, Range]]] = {}

    def add(
        self, name: str, version: str, requires: dict[str, str] | None = None
    ) -> None:
        """
        Add a release to the index.

        Args:
            name: The package name.
            version: The version string (e.g. "1.0.0").
            requires: A dict mapping dependency names to range specs.

        Raises:
            ValueError: If the version is invalid, a spec is invalid, or the
                package name and version are already present.
        """
        try:
            v = Version(version)
        except ValueError:
            raise ValueError(f"Invalid version string: {version!r}") from None

        if name not in self._data:
            self._data[name] = {}

        if v in self._data[name]:
            raise ValueError(
                f"Package {name!r} version {version!r} is already added"
            )

        deps: dict[str, Range] = {}
        if requires:
            for dep_name, spec in requires.items():
                try:
                    r = Range(spec)
                except ValueError:
                    raise ValueError(
                        f"Invalid range spec for dependency {dep_name!r}: {spec!r}"
                    ) from None
                deps[dep_name] = r

        self._data[name][v] = deps

    def versions(self, name: str) -> list[Version]:
        """
        Return the list of known Versions of a package, newest first.

        Args:
            name: The package name.

        Returns:
            A list of Version objects, sorted in descending order (newest first).
            Returns an empty list if the name is unknown.
        """
        if name not in self._data:
            return []
        # Get keys and sort them. Version supports __lt__ so it is sortable.
        # newest first means descending order.
        return sorted(self._data[name].keys(), reverse=True)

    def requirements(self, name: str, version: Version) -> dict[str, Range]:
        """
        Return the dependencies for a specific package release.

        Args:
            name: The package name.
            version: The Version object.

        Returns:
            A dict mapping dependency names to Range objects.

        Raises:
            KeyError: If the name or version is not found in the index.
        """
        if name not in self._data:
            raise KeyError(f"Package {name!r} is not in the index")
        if version not in self._data[name]:
            raise KeyError(
                f"Version {version} of package {name!r} is not in the index"
            )
        return self._data[name][version]

    @classmethod
    def from_dict(cls, data: dict[str, dict[str, dict[str, str]]]) -> PackageIndex:
        """
        Build a PackageIndex from a nested dictionary.

        Args:
            data: A dictionary of the form::

                {
                    "package_name": {
                        "1.0.0": {"dep": ">=1.0.0"},
                        "1.1.0": {},
                    },
                    ...
                }

        Returns:
            A populated PackageIndex instance.
        """
        index = cls()
        for name, versions_map in data.items():
            for version_str, requires_map in versions_map.items():
                index.add(name, version_str, requires_map)
        return index
