# resolve/solver.py
from __future__ import annotations

from .index import PackageIndex
from .versions import Version, Range


class ResolutionError(Exception):
    """Raised when dependency resolution fails."""

    def __init__(self, package: str, explanation: str) -> None:
        super().__init__(explanation)
        self.package = package
        self.explanation = explanation

    def __str__(self) -> str:
        return self.explanation


def resolve(index: PackageIndex, requirements: dict[str, str]) -> dict[str, Version]:
    """
    Resolve package dependencies using depth-first search with backtracking.
    """
    # Parse root requirements to catch ValueError early
    root_ranges = {}
    for name, spec in requirements.items():
        try:
            root_ranges[name] = Range(spec)
        except ValueError as e:
            raise ValueError(f"Invalid requirement spec for {name!r}: {spec!r}") from e

    # Initial order: root requirement names sorted alphabetically
    order = sorted(root_ranges.keys())
    selected: dict[str, Version] = {}

    def get_constraints(name: str, order: list[str], selected: dict[str, Version]) -> list[tuple[str, Range]]:
        """
        Gather constraints for `name` from root and selected packages.
        Returns list of (requirer_string, Range).
        """
        constraints = []
        # Root constraints
        if name in root_ranges:
            constraints.append(("<root>", root_ranges[name]))

        # Selected packages' constraints
        # We need to iterate selected in order of selection? 
        # The prompt says: "followed by the requirements on it of the selected packages, in selection order."
        # Python dicts preserve insertion order since 3.7.
        # selected is a dict, so we can iterate items().
        for pkg, ver in selected.items():
            try:
                deps = index.requirements(pkg, ver)
            except KeyError:
                # Should not happen if selected is valid
                continue
            if name in deps:
                constraints.append((f"{pkg} {ver}", deps[name]))

        return constraints

    def is_acceptable(name: str, version: Version, constraints: list[tuple[str, Range]], selected: dict[str, Version]) -> bool:
        """
        Check if version satisfies all constraints and is compatible with selected deps.
        """
        # Check constraints
        for _, r in constraints:
            if not r.contains(version):
                return False

        # Check dependencies against already selected packages
        try:
            deps = index.requirements(name, version)
        except KeyError:
            return False # Should be caught by candidates list, but safety check

        for dep_name, r in deps.items():
            if dep_name in selected:
                if not r.contains(selected[dep_name]):
                    return False
        return True

    def build_explanation(name: str, constraints: list[tuple[str, Range]], index: PackageIndex, selected: dict[str, Version]) -> str:
        """
        Construct the explanation string for a failed resolution of `name`.
        """
        lines = [f"cannot resolve {name}"]

        # Constraint lines
        for requirer, r in constraints:
            lines.append(f"  {requirer} requires {name} {r}")

        versions = index.versions(name)
        if not versions:
            lines.append(f"  no versions of {name} are known")
            return "\n".join(lines)

        # Version lines
        for v in versions:
            # Check if excluded by constraints
            excluded = False
            for _, r in constraints:
                if not r.contains(v):
                    excluded = True
                    break

            if excluded:
                lines.append(f"  {name} {v} is excluded by the constraints")
            else:
                # Must be excluded by dependency conflicts
                # Find first conflicting dependency in alphabetical order
                deps = index.requirements(name, v)
                conflict_found = False
                for dep_name in sorted(deps.keys()):
                    if dep_name in selected:
                        r = deps[dep_name]
                        if not r.contains(selected[dep_name]):
                            lines.append(f"  {name} {v} requires {dep_name} {r}, but {dep_name} {selected[dep_name]} is selected")
                            conflict_found = True
                            break
                if not conflict_found:
                    # This case should theoretically not happen if it was filtered as "acceptable" logic failed,
                    # but if we are here, it means constraints passed and deps selected passed? 
                    # Wait, if we are in build_explanation, it means NO acceptable candidate was found.
                    # If a version passed constraints and deps check, it WOULD be acceptable.
                    # So all versions MUST be excluded by constraints OR deps check.
                    # If not excluded by constraints, it MUST be excluded by deps check.
                    # So conflict_found should always be True if not excluded by constraints.
                    # If not, something is wrong, but we'll skip.
                    pass

        return "\n".join(lines)

    def dfs(order: list[str], selected: dict[str, Version]) -> tuple[dict[str, Version] | None, ResolutionError | None]:
        """
        Depth-first search.
        Returns (solution, error).
        """
        # 1. Find next unselected name in order
        current_name = None
        for name in order:
            if name not in selected:
                current_name = name
                break

        # If no unselected names, we are done
        if current_name is None:
            return (selected.copy(), None)

        # 2. Get constraints
        constraints = get_constraints(current_name, order, selected)

        # 3. Get candidates
        candidates = index.versions(current_name)

        # 4. Filter acceptable candidates
        acceptable = []
        for v in candidates:
            if is_acceptable(current_name, v, constraints, selected):
                acceptable.append(v)

        # If no acceptable candidates, fail here
        if not acceptable:
            explanation = build_explanation(current_name, constraints, index, selected)
            return (None, ResolutionError(current_name, explanation))

        first_error = None

        for v in acceptable:
            # Select
            new_selected = selected.copy()
            new_selected[current_name] = v

            # Add dependencies to order
            deps = index.requirements(current_name, v)
            new_names = []
            for dep_name in sorted(deps.keys()): # Alphabetical order for new names
                if dep_name not in order and dep_name not in selected:
                    new_names.append(dep_name)

            # Append new names to order
            # Note: We only add names not already in order.
            # Also need to check if they are in new_selected? 
            # The prompt says "append its dependency names that are not yet in the order to the order (in alphabetical order)"
            # "not yet in the order" implies checking against the current order list.
            new_order = order + new_names

            # Recurse
            result, err = dfs(new_order, new_selected)

            if result is not None:
                return (result, None)

            if err is not None and first_error is None:
                first_error = err

        return (None, first_error)

    result, err = dfs(order, selected)

    if result is not None:
        return result

    if err is not None:
        raise err

    # Should not reach here if search failed properly, but if root had no items?
    # If root requirements is empty, order is empty. dfs returns ({}, None). Result {}.
    # If root has items but fails, err is set.
    raise ResolutionError("root", "cannot resolve root")
