            upper_ver = Version(f"{ver.major + 1}.0.0")
        elif ver.minor != 0:
            upper_ver = Version(f"0.{ver.minor + 1}.0")
        elif ver.patch != 0:
            upper_ver = Version(f"0.0.{ver.patch + 1}")
