    def __str__(self) -> str:
        return self.explanation


def resolve(index: PackageIndex, requirements: dict[str, str]) -> dict[str, Version]:
    """
    Resolve package dependencies using depth-first search with backtracking.
    """
    # Parse root requirements to catch ValueError early
    root_ranges = {}
    for name, spec in requirements.items():
        try:
            root_ranges[name] = Range(spec)
        except ValueError as e:
            raise ValueError(f"Invalid requirement spec for {name!r}: {spec!r}") from e

    # Initial order: root requirement names sorted alphabetically
    order = sorted(root_ranges.keys())
    selected: dict[str, Version] = {}

    def get_constraints(name: str, order: list[str], selected: dict[str, Version]) -> list[tuple[str, Range]]:
        """
        Gather constraints for `name` from root and selected packages.
        Returns list of (requirer_string, Range).
        """
        constraints = []
        # Root constraints
        if name in root_ranges:
            constraints.append(("<root>", root_ranges[name]))

        # Selected packages' constraints
        # We need to iterate selected in order of selection? 
        # The prompt says: "followed by the requirements on it of the selected packages, in selection order."
        # Python dicts preserve insertion order since 3.7.
        # selected is a dict, so we can iterate items().
        for pkg, ver in selected.items():
            try:
                deps = index.requirements(pkg, ver)
            except KeyError:
                # Should not happen if selected is valid
                continue
            if name in deps:
                constraints.append((f"{pkg} {ver}", deps[name]))

        return constraints

    def is_acceptable(name: str, version: Version, constraints: list[tuple[str, Range]], selected: dict[str, Version]) -> bool:
        """
        Check if version satisfies all constraints and is compatible with selected deps.
        """
        # Check constraints
        for _, r in constraints:
            if not r.contains(version):
                return False

        # Check dependencies against already selected packages
        try:
            deps = index.requirements(name, version)
        except KeyError:
            return False # Should be caught by candidates list, but safety check

        for dep_name, r in deps.items():
            if dep_name in selected:
                if not r.contains(selected[dep_name]):
                    return False
        return True

    def build_explanation(name: str, constraints: list[tuple[str, Range]], index: PackageIndex, selected: dict[str, Version]) -> str:
        """
        Construct the explanation string for a failed resolution of `name`.
        """
        lines = [f"cannot resolve {name}"]

        # Constraint lines
        for requirer, r in constraints:
            lines.append(f"  {requirer} requires {name} {r}")

        versions = index.versions(name)
        if not versions:
            lines.append(f"  no versions of {name} are known")
            return "\n".join(lines)

        # Version lines
        for v in versions:
            # Check if excluded by constraints
            excluded = False
            for _, r in constraints:
                if not r.contains(v):
                    excluded = True
                    break

            if excluded:
                lines.append(f"  {name} {v} is excluded by the constraints")
            else:
                # Must be excluded by dependency conflicts
                # Find first conflicting dependency in alphabetical order
                deps = index.requirements(name, v)
                conflict_found = False
                for dep_name in sorted(deps.keys()):
                    if dep_name in selected:
                        r = deps[dep_name]
                        if not r.contains(selected[dep_name]):
                            lines.append(f"  {name} {v} requires {dep_name} {r}, but {dep_name} {selected[dep_name]} is selected")
                            conflict_found = True
                            break
                if not conflict_found:
                    # This case should theoretically not happen if it was filtered as "acceptable" logic failed,
                    # but if we are here, it means constraints passed and deps selected passed? 
                    # Wait, if we are in build_explanation, it means NO acceptable candidate was found.
                    # If a version passed constraints and deps check, it WOULD be acceptable.
                    # So all versions MUST be excluded by constraints OR deps check.
                    # If not excluded by constraints, it MUST be excluded by deps check.
                    # So conflict_found should always be True if not excluded by constraints.
                    # If not, something is wrong, but we'll skip.
                    pass

        return "\n".join(lines)

    def dfs(order: list[str], selected: dict[str, Version]) -> tuple[dict[str, Version] | None, ResolutionError | None]:
        """
        Depth-first search.
        Returns (solution, error).
        """
        # 1. Find next unselected name in order
        current_name = None
        for name in order:
            if name not in selected:
                current_name = name
                break

        # If no unselected names, we are done
        if current_name is None:
            return (selected.copy(), None)

        # 2. Get constraints
        constraints = get_constraints(current_name, order, selected)

        # 3. Get candidates
        candidates = index.versions(current_name)

        # 4. Filter acceptable candidates
        acceptable = []
        for v in candidates:
            if is_acceptable(current_name, v, constraints, selected):
                acceptable.append(v)

        # If no acceptable candidates, fail here
        if not acceptable:
            explanation = build_explanation(current_name, constraints, index, selected)
            return (None, ResolutionError(current_name, explanation))

        first_error = None

        for v in acceptable:
            # Select
            new_selected = selected.copy()
            new_selected[current_name] = v

            # Add dependencies to order
            deps = index.requirements(current_name, v)
            new_names = []
            for dep_name in sorted(deps.keys()): # Alphabetical order for new names
                if dep_name not in order and dep_name not in selected:
                    new_names.append(dep_name)

            # Append new names to order
            # Note: We only add names not already in order.
            # Also need to check if they are in new_selected? 
            # The prompt says "append its dependency names that are not yet in the order to the order (in alphabetical order)"
            # "not yet in the order" implies checking against the current order list.
            new_order = order + new_names

            # Recurse
            result, err = dfs(new_order, new_selected)

            if result is not None:
                return (result, None)

            if err is not None and first_error is None:
                first_error = err

        return (None, first_error)

    result, err = dfs(order, selected)

    if result is not None:
        return result

    if err is not None:
        raise err

    # Should not reach here if search failed properly, but if root had no items?
    # If root requirements is empty, order is empty. dfs returns ({}, None). Result {}.
    # If root has items but fails, err is set.
    raise ResolutionError("root", "cannot resolve root")

# logagg/parsers.py
import re
import json
from datetime import datetime, timezone
from dataclasses import dataclass
from typing import Optional


class ParseError(ValueError):
    pass


@dataclass(frozen=True)
class Record:
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: float | None


def normalize(time, client, method, path, status, size, latency_ms) -> Record:
    # Time
    if not isinstance(time, datetime):
        raise ParseError("time must be a datetime")
    if time.tzinfo is None:
        raise ParseError("time must be timezone-aware")
    time = time.astimezone(timezone.utc)

    # Client
    if not isinstance(client, str) or not client:
        raise ParseError("client must be a non-empty string")

    # Method
    if not isinstance(method, str) or not method:
        raise ParseError("method must be a non-empty string")
    if not method.isascii():
        raise ParseError("method must be ASCII")
    method = method.upper()
    if not method.isalpha():
        raise ParseError("method must contain only ASCII letters")

    # Path
    if not isinstance(path, str) or not path.startswith("/"):
        raise ParseError("path must start with /")
    # Remove fragment and query
    path = path.split('#')[0]
    path = path.split('?')[0]
    # Collapse slashes
    path = re.sub(r'/+', '/', path)

    # Status
    if isinstance(status, str):
        if not status.isdigit():
            raise ParseError("status string must be digits")
        status = int(status)
    elif not isinstance(status, int):
        raise ParseError("status must be int or digit string")
    if not (100 <= status <= 599):
        raise ParseError("status out of range")

    # Size
    if size is None or size == "-":
        size = 0
    elif isinstance(size, str):
        if not size.isdigit():
            raise ParseError("size string must be digits")
        size = int(size)
    elif not isinstance(size, int):
        raise ParseError("size must be int")
    if size < 0:
        raise ParseError("size must be non-negative")

    # Latency
    if latency_ms is not None:
        if isinstance(latency_ms, (int, float)):
            latency_ms = float(latency_ms)
        elif isinstance(latency_ms, str):
            try:
                latency_ms = float(latency_ms)
            except ValueError:
                raise ParseError("latency_ms invalid")
        else:
            raise ParseError("latency_ms invalid type")
        if latency_ms < 0:
            raise ParseError("latency_ms must be non-negative")

    return Record(
        time=time,
        client=client,
        method=method,
        path=path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )


_CLF_RE = re.compile(
    r'(?P<client>\S+)\s+'
    r'(?P<ident>\S+)\s+'
    r'(?P<user>\S+)\s+'
    r'\[(?P<time>[^\]]+)\]\s+'
    r'"(?P<request>[^"]*)"\s+'
    r'(?P<status>\d+)\s+'
    r'(?P<size>\d+|\-)(?:\s+(?P<latency_us>\d+))?$'
)

_MONTHS = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
}

def _parse_clf_time(time_str):
    # DD/Mon/YYYY:HH:MM:SS ±HHMM
    m = re.match(r'(\d{2})/(\w{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2})\s+([+-])(\d{2})(\d{2})', time_str)
    if not m:
        raise ParseError("Invalid time format")
    day, mon_str, year, hour, minute, sec, sign, tz_hour, tz_min = m.groups()
    mon = _MONTHS.get(mon_str)
    if not mon:
        raise ParseError("Invalid month")
    sign_val = 1 if sign == '+' else -1
    tz = timezone(sign_val * (int(tz_hour) * 3600 + int(tz_min) * 60))
    try:
        dt = datetime(int(year), mon, int(day), int(hour), int(minute), int(sec), tzinfo=tz)
    except ValueError:
        raise ParseError("Invalid date values")
    return dt

def parse_clf(line):
    line = line.strip()
    if not line:
        raise ParseError("Empty line")
    m = _CLF_RE.match(line)
    if not m:
        raise ParseError("Line does not match CLF pattern")

    time = _parse_clf_time(m.group('time'))
    client = m.group('client')

    request = m.group('request')
    parts = request.split(' ')
    if len(parts) != 3:
        raise ParseError("Request line must have 3 parts")
    method, path, _ = parts

    status = m.group('status')
    size = m.group('size')
    latency_us = m.group('latency_us')

    latency_ms = None
    if latency_us:
        latency_ms = int(latency_us) / 1000.0

    return normalize(
        time=time,
        client=client,
        method=method,
        path=path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

def parse_jsonl(line):
    line = line.strip()
    if not line:
        raise ParseError("Empty line")
    try:
        obj = json.loads(line)
    except json.JSONDecodeError:
        raise ParseError("Invalid JSON")

    if not isinstance(obj, dict):
        raise ParseError("JSON root must be object")

    try:
        ts_str = obj['ts']
        client = obj['client']
        method = obj['method']
        path = obj['path']
        status = obj['status']
    except KeyError as e:
        raise ParseError(f"Missing required key: {e}")

    if not isinstance(ts_str, str):
        raise ParseError("ts must be string")

    # Parse ISO 8601 with offset/Z
    # Python 3.11+ datetime.fromisoformat handles Z
    # We ensure it has an offset
    ts_str = ts_str.replace('Z', '+00:00')
    try:
        time = datetime.fromisoformat(ts_str)
    except ValueError:
        raise ParseError("Invalid ISO time")

    if time.tzinfo is None:
        raise ParseError("ts must include offset")

    size = obj.get('bytes')
    latency_ms = obj.get('latency_ms')

    return normalize(
        time=time,
        client=client,
        method=method,
        path=path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

def parse_line(line, fmt='auto'):
    if fmt == 'clf':
        return parse_clf(line)
    elif fmt == 'jsonl':
        return parse_jsonl(line)
    elif fmt == 'auto':
        if line.lstrip().startswith('{'):
            return parse_jsonl(line)
        else:
            return parse_clf(line)
    else:
        raise ValueError("Invalid format")

def read_records(lines, fmt='auto'):
    records = []
    bad_indices = []

    for i, line in enumerate(lines):
        # Lines are 1-based in the output bad list
        line_no = i + 1
        stripped = line.strip()
        if not stripped:
            continue

        try:
            rec = parse_line(line, fmt)
            records.append(rec)
        except ParseError:
            bad_indices.append(line_no)

    return records, bad_indices
